const OfferBlock = () => {
  const [timeLeft, setTimeLeft] = useState(16 * 60);
  const timerRef = useRef<HTMLDivElement>(null);
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && !started) {
        setStarted(true);
      }
    }, { threshold: 0.1 });

    if (timerRef.current) {
      observer.observe(timerRef.current);
    }

    return () => observer.disconnect();
  }, [started]);

  useEffect(() => {
    if (!started || timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [started, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <Section id="oferta" className="scroll-mt-10">
      <div className="bg-white rounded-3xl p-8 shadow-2xl border-4 border-[#606C38] offer-pulse">
        <h2 className="text-3xl font-bold text-center mb-6">Cafés da Manhã no Pote</h2>
        <div className="mb-8">
          <img src="https://res.cloudinary.com/drcqck3r9/image/upload/v1771010068/7_te3pbr.webp" alt="Mockup do Guia" className="w-full h-auto" />
        </div>
        <div className="space-y-3 mb-8">
          <div className="flex gap-2"><CheckCircle2 className="text-[#606C38]" /> <span className="font-bold">+30 Receitas de Cafés da Manhã no Pote</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#606C38]" /> <span className="font-bold">Lista de Compras Econômica</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#606C38]" /> <span className="font-bold">Sobremesas Fit no Pote</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#606C38]" /> <span className="font-bold">30 Marmitas Fit P/Congelar</span></div>
        </div>
        <div className="text-center mb-8">
          <p className="text-gray-400 line-through text-xl">De R$99,90</p>
          <p className="text-lg font-bold text-[#606C38] uppercase">por apenas</p>
          <p className="text-6xl font-bold text-[#2C1E12]">R$10,00</p>
        </div>
        <Button className="bg-[#606C38] text-white py-6 text-xl mb-6 shadow-[#606C38]/40 shadow-xl">
          QUERO COMPRAR AGORA
        </Button>
        <div ref={timerRef} className="text-center bg-red-50 py-3 rounded-xl mb-6">
          <p className="text-red-600 font-bold flex items-center justify-center gap-2">
            <Clock size={20} /> ESSA OFERTA EXPIRA EM {formatTime(timeLeft)}
          </p>
        </div>
        <div className="flex items-center justify-center gap-4 text-xs font-bold text-gray-500 uppercase">
          <span className="flex items-center gap-1"><ShieldCheck size={14} className="text-green-600" /> Compra 100% Segura</span>
          <span>•</span>
          <span>7 Dias de Garantia</span>
        </div>
