const OfferBlock = () => {
  const [timeLeft, setTimeLeft] = useState(16 * 60);
  const timerRef = useRef<HTMLDivElement>(null);
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && !started) {
        setStarted(true);
      }
    }, { threshold: 0.1 });

    if (timerRef.current) {
      observer.observe(timerRef.current);
    }

    return () => observer.disconnect();
  }, [started]);

  useEffect(() => {
    if (!started || timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [started, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <Section id="oferta" className="scroll-mt-10 bg-[#FFFFFF]">
      <div className="bg-[#F6F3ED] rounded-3xl p-8 shadow-2xl border-4 border-[#2F7D32] offer-pulse">
