          Cafés da Manhã <Highlight>no Pote</Highlight>
        </h2>
        <div className="mb-8">
          <img src="https://res.cloudinary.com/drcqck3r9/image/upload/v1771010068/7_te3pbr.webp" alt="Mockup do Guia" className="w-full h-auto" />
        </div>
        <div className="space-y-3 mb-8">
          <div className="flex gap-2"><CheckCircle2 className="text-[#2F7D32]" /> <span className="font-bold text-[#4A4A4A] text-sm md:text-base">+30 Receitas de Cafés da Manhã no Pote</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#2F7D32]" /> <span className="font-bold text-[#4A4A4A] text-sm md:text-base">Lista de Compras Econômica</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#2F7D32]" /> <span className="font-bold text-[#4A4A4A] text-sm md:text-base">Sobremesas Fit no Pote</span></div>
          <div className="flex gap-2"><CheckCircle2 className="text-[#2F7D32]" /> <span className="font-bold text-[#4A4A4A] text-sm md:text-base">30 Marmitas Fit P/Congelar</span></div>
        </div>
        <div className="text-center mb-8">
          <p className="text-[#7A7A7A] line-through text-lg">De R$99,90</p>
          <p className="text-sm font-bold text-[#B45309] uppercase tracking-tight">por apenas</p>
          <p className="text-5xl font-bold text-[#34A853]">R$10,00</p>
        </div>
        <Button className="py-6 text-xl mb-6 shadow-xl shadow-[#2F7D32]/30">
          QUERO COMPRAR AGORA
        </Button>
        <div ref={timerRef} className="text-center bg-[#E53935]/5 py-3 rounded-xl mb-6">
          <p className="text-[#E53935] font-bold flex items-center justify-center gap-2">
            <Clock size={20} /> ESSA OFERTA EXPIRA EM {formatTime(timeLeft)}
          </p>
        </div>
        <div className="flex items-center justify-center gap-4 text-[10px] md:text-xs font-bold text-[#7A7A7A] uppercase">
