const OfferBlock = () => {
  const [timeLeft, setTimeLeft] = useState(16 * 60);
  const timerRef = useRef<HTMLDivElement>(null);
  const [started, setStarted] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && !started) {
        setStarted(true);
      }
    }, { threshold: 0.1 });

    if (timerRef.current) {
      observer.observe(timerRef.current);
    }

    return () => observer.disconnect();
  }, [started]);

  useEffect(() => {
    if (!started || timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [started, timeLeft]);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <Section id="oferta" className="scroll-mt-10 bg-[#FFFFFF]">
      <div className="bg-[#FDFBF7] rounded-[40px] p-8 md:p-12 shadow-[0_20px_60px_rgba(47,125,50,0.12)] border border-[#2F7D32]/10 relative overflow-hidden flex flex-col items-center">
        <div className="mb-12 scale-125 md:scale-150 transform transition-transform duration-700 hover:scale-[1.55]">
          <img src="https://res.cloudinary.com/drcqck3r9/image/upload/v1771010068/7_te3pbr.webp" alt="Mockup do Guia" className="w-full h-auto drop-shadow-2xl" />
        </div>

        <div className="space-y-4 mb-10 w-full max-w-sm mx-auto">
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">+30 Receitas de Cafés da Manhã no Pote</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">Lista de Compras Econômica</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">Sobremesas Fit no Pote</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">30 Marmitas Fit P/Congelar</span></div>
        </div>

        <div className="text-center mb-10">
          <p className="text-[#7A7A7A] line-through text-xl mb-1">De R$99,90</p>
          <p className="text-sm font-bold text-[#B45309] uppercase tracking-widest mb-2">POR APENAS</p>
          <p className="text-7xl font-bold text-[#34A853] tracking-tighter">R$10,00</p>
        </div>

        <div className="w-full mb-8 max-w-md mx-auto">
          <Button className="py-5 text-xl btn-pulse shadow-[#2F7D32]/40 whitespace-nowrap overflow-hidden text-ellipsis">
            QUERO COMPRAR AGORA
          </Button>
        </div>

        <div ref={timerRef} className="text-center mb-10">
          <p className="text-[#E53935] font-bold text-lg flex items-center justify-center gap-2">
            <Clock size={20} /> ESSA OFERTA EXPIRA EM {formatTime(timeLeft)}
