          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">Sobremesas Fit no Pote</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">30 Marmitas Fit P/Congelar</span></div>
        </div>

        <div className="text-center mb-10">
          <p className="text-[#7A7A7A] line-through text-xl mb-1">De R$99,90</p>
          <p className="text-sm font-bold text-[#B45309] uppercase tracking-widest mb-2">POR APENAS</p>
          <p className="text-7xl font-bold text-[#34A853] tracking-tighter">R$10,00</p>
        </div>

        <div className="w-full mb-8 max-w-md mx-auto">
          <Button className="py-5 text-base sm:text-lg btn-pulse shadow-[#2F7D32]/40 whitespace-nowrap px-4">
            QUERO COMPRAR AGORA
          </Button>
        </div>

        <div ref={timerRef} className="text-center mb-10">
