          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg">+30 Receitas de Cafés da Manhã no Pote</span></div>
