        <div className="mb-12 scale-125 md:scale-150 transform transition-transform duration-700 hover:scale-[1.55]">
          <img src="https://res.cloudinary.com/drcqck3r9/image/upload/v1771010068/7_te3pbr.webp" alt="Mockup do Guia" className="w-full h-auto drop-shadow-2xl" />
        </div>

        <div className="space-y-4 mb-10 w-full max-w-sm mx-auto">
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg uppercase">+30 Receitas de Cafés da Manhã no Pote</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg uppercase">Lista de Compras Econômica</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg uppercase">Sobremesas Fit no Pote</span></div>
          <div className="flex gap-3 items-center"><CheckCircle2 className="text-[#2F7D32]" size={22} /> <span className="font-bold text-[#4A4A4A] text-base md:text-lg uppercase">30 Marmitas Fit P/Congelar</span></div>
        </div>

        <div className="text-center mb-10">
          <p className="text-[#7A7A7A] line-through text-xl mb-1 uppercase">De R$99,90</p>
          <p className="text-sm font-bold text-[#B45309] uppercase tracking-widest mb-2">POR APENAS</p>
          <p className="text-7xl font-bold text-[#34A853] tracking-tighter uppercase">R$10,00</p>
        </div>

        <div className="w-full mb-8 max-w-md mx-auto">
          <Button className="py-5 shadow-[#34A853]/40">
            QUERO COMPRAR AGORA
          </Button>
        </div>

        <div ref={timerRef} className="text-center mb-10">
