  if (href) {
    return (
      <a 
        href={href}
        className={`no-underline ${baseClasses}`}
      >
        {children}
      </a>
    );
  }
  return (
    <button 
      onClick={onClick}
      className={baseClasses}
    >
      {children}
    </button>
  );
};

